SELECT CAST(COUNT(DISTINCT CASE WHEN t.drug_type = 'Antidiabetic' AND t.drug_code IN (SELECT code FROM d_items WHERE category = 'Antidiabetic') AND t.starttime <= i.intime AND t.endtime >= i.intime THEN t.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT i.subject_id), 0) AS proportion_antidiabetic_first_24h, CAST(COUNT(DISTINCT CASE WHEN t.drug_type = 'Antidiabetic' AND t.drug_code IN (SELECT code FROM d_items WHERE category = 'Antidiabetic') AND t.starttime <= i.intime + interval '48 hours' AND t.endtime >= i.intime + interval '48 hours' THEN t.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT i.subject_id), 0) AS proportion_antidiabetic_final_48h, COUNT(DISTINCT CASE WHEN t.drug_type = 'Beta-Blocker' AND t.drug_code IN (SELECT code FROM d_items WHERE category = 'Beta-Blocker') AND t.starttime <= i.intime AND t.endtime >= i.intime THEN t.subject_id END) AS num_beta_blockers_start_to_end, COUNT(DISTINCT CASE WHEN t.drug_type = 'Beta-Blocker' AND t.drug_code IN (SELECT code FROM d_items WHERE category = 'Beta-Blocker') AND t.starttime <= i.intime + interval '48 hours' AND t.endtime >= i.intime + interval '48 hours' THEN t.subject_id END) AS num_beta_blockers_start_to_end_48h, COUNT(DISTINCT CASE WHEN t.drug_type = 'ACEi/ARB/ARNI' AND t.drug_code IN (SELECT code FROM d_items WHERE category = 'ACEi/ARB/ARNI') AND t.starttime <= i.intime AND t.endtime >= i.intime THEN t.subject_id END) AS num_ace_start_to_end, COUNT(DISTINCT CASE WHEN t.drug_type = 'ACEi/ARB/ARNI' AND t.drug_code IN (SELECT code FROM d_items WHERE category = 'ACEi/ARB/ARNI') AND t.starttime <= i.intime + interval '48 hours' AND t.endtime >= i.intime + interval '48 hours' THEN t.subject_id END) AS num_ace_start_to_end_48h, COUNT(DISTINCT CASE WHEN t.drug_type = 'Loop Diuretic' AND t.drug_code IN (SELECT code FROM d_items WHERE category = 'Loop Diuretic') AND t.starttime <= i.intime AND t.endtime >= i.intime THEN t.subject_id END) AS num_loop_diuretic_start_to_end, COUNT(DISTINCT CASE WHEN t.drug_type = 'Loop Diuretic' AND t.drug_code IN (SELECT code FROM d_items WHERE category = 'Loop Diuretic') AND t.starttime <= i.intime + interval '48 hours' AND t.endtime >= i.intime + interval '48 hours' THEN t.subject_id END) AS num_loop_diuretic_start_to_end_48h FROM physionet-data.mimiciv_3_1_hosp.prescriptions t JOIN physionet-data.mimiciv_3_1_icu.inputevents i ON t.subject_id = i.subject_id WHERE t.subject_id IN (SELECT subject_id FROM physionet-data.mimiciv_3_1_hosp.admissions WHERE gender = 'M' AND age >= 54 AND (icd9_code IN ('42885', '42886') OR (icd9_code IN ('42885', '42886') AND (start_date <= '2020-01-01' AND end_date >= '2020-12-31')))) AND (t.starttime <= i.intime AND t.endtime >= i.intime) AND (t.starttime <= i.intime + interval '48 hours' AND t.endtime >= i.intime + interval '48 hours');